#!/usr/bin/env ruby
# frozen_string_literal: true

# Codegen "middle path" (CLAUDE.md §5): generate each core's integrity-check finding kinds and skip
# reasons from the canonical spec/integrity/findings.toml (spec/design/integrity-check.md §4). This
# emits the names only; the check that reports them is hand-written per core. Build-time only.
#
#   ruby scripts/gen_integrity.rb            # (re)write the generated files
#   ruby scripts/gen_integrity.rb --check    # fail if any checked-in file is stale

require "bundler/setup"
require "toml-rb"

REPO = File.expand_path("..", __dir__)
REGISTRY = File.join(REPO, "spec", "integrity", "findings.toml")

TARGETS = [
  ["impl/rust/src/integrity_kinds.rs", :rust_file],
  ["impl/go/integrity_kinds.go",       :go_file],
  ["impl/ts/src/integrity_kinds.ts",   :ts_file],
].freeze

HEADER = "GENERATED by scripts/gen_integrity.rb from spec/integrity/findings.toml — do not edit."

def fail!(msg)
  warn "FAIL: #{msg}"
  exit 1
end

def registry = @registry ||= TomlRB.load_file(REGISTRY)
def findings = registry.fetch("finding")
def skips = registry.fetch("skip")

def pascal(name) = name.split("_").map(&:capitalize).join
def camel(name) = pascal(name).sub(/\A./, &:downcase)

def rust_file
  out = +"// #{HEADER}\n//\n// Integrity-check finding kinds and skip reasons (spec/design/integrity-check.md §4).\n\n"
  findings.each { |f| out << "/// #{f['description']}\npub const #{f['kind'].upcase}: &str = \"#{f['kind']}\";\n" }
  out << "\n/// Every finding kind, in registry order.\npub const FINDING_KINDS: &[&str] = &[\n"
  findings.each { |f| out << "    #{f['kind'].upcase},\n" }
  out << "];\n\n"
  skips.each { |s| out << "/// #{s['description']}\npub const SKIP_#{s['reason'].upcase}: &str = \"#{s['reason']}\";\n" }
  out << "\n/// Every skip reason, in registry order.\npub const SKIP_REASONS: &[&str] = &[\n"
  skips.each { |s| out << "    SKIP_#{s['reason'].upcase},\n" }
  out << "];\n"
end

def go_file
  out = +"// #{HEADER}\n\npackage jed\n\n"
  out << "// Integrity-check finding kinds (spec/design/integrity-check.md §4).\nconst (\n"
  findings.each { |f| out << "\t// Integrity#{pascal(f['kind'])}: #{f['description']}\n\tIntegrity#{pascal(f['kind'])} = \"#{f['kind']}\"\n" }
  out << ")\n\n// Integrity-check skip reasons (spec/design/integrity-check.md §3.5).\nconst (\n"
  skips.each { |s| out << "\t// IntegritySkip#{pascal(s['reason'])}: #{s['description']}\n\tIntegritySkip#{pascal(s['reason'])} = \"#{s['reason']}\"\n" }
  out << ")\n\n// integrityFindingKinds lists every finding kind, in registry order.\nvar integrityFindingKinds = []string{\n"
  findings.each { |f| out << "\tIntegrity#{pascal(f['kind'])},\n" }
  out << "}\n\n// integritySkipReasons lists every skip reason, in registry order.\nvar integritySkipReasons = []string{\n"
  skips.each { |s| out << "\tIntegritySkip#{pascal(s['reason'])},\n" }
  out << "}\n"
end

def ts_file
  out = +"// #{HEADER}\n\n"
  out << "/** Integrity-check finding kinds (spec/design/integrity-check.md §4). */\nexport const IntegrityKind = {\n"
  findings.each { |f| out << "  /** #{f['description']} */\n  #{camel(f['kind'])}: \"#{f['kind']}\",\n" }
  out << "} as const;\n\nexport type IntegrityKindName = (typeof IntegrityKind)[keyof typeof IntegrityKind];\n\n"
  out << "/** Integrity-check skip reasons (spec/design/integrity-check.md §3.5). */\nexport const IntegritySkipReason = {\n"
  skips.each { |s| out << "  /** #{s['description']} */\n  #{camel(s['reason'])}: \"#{s['reason']}\",\n" }
  out << "} as const;\n\nexport type IntegritySkipReasonName =\n  (typeof IntegritySkipReason)[keyof typeof IntegritySkipReason];\n"
end

check = ARGV.include?("--check")
stale = TARGETS.reject do |rel, builder|
  path = File.join(REPO, rel)
  body = send(builder)
  next File.exist?(path) && File.read(path) == body if check

  File.write(path, body)
  true
end
fail!("stale generated files: #{stale.map(&:first).join(', ')} (run ruby scripts/gen_integrity.rb)") if check && !stale.empty?
puts check ? "OK: #{TARGETS.size} generated files current (#{findings.size} kinds, #{skips.size} skip reasons)" : "wrote #{TARGETS.size} files"
